public static int findNthLeapYear(int Y, int N) {
  if (Y < 1 || N < 1) {
    throw new IllegalArgumentException("Both the start year and the position of the leap year to find must be positive integers.");
  }

  // Calculate the total number of leap years between year 1 and the start year
  int leapYearsBeforeStartYear = 0;
  for (int year = 1; year < Y; year++) {
    if (isLeapYear(year)) {
      leapYearsBeforeStartYear++;
    }
  }

  // Find the Nth leap year after the start year
  int year = Y;
  while (N > 0) {
    year += 4;
    if (isLeapYear(year)) {
      N--;
    }
  }

  return year;
}

