public double trimMean(int[] arr) {
    int n = arr.length;
    if (n < 2) {
        throw new IllegalArgumentException("Invalid array length: " + n);
    }

    // Sort the array
    Arrays.sort(arr);

    // Calculate the smallest and largest 5% of the elements
    int smallest = (int) Math.ceil(n * 0.05);
    int largest = (int) Math.floor(n * 0.95);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = smallest; i < largest; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    double mean = sum / (largest - smallest);

    return mean;
}

