public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] counter = new int[n];  // Counter array to keep track of occurrences of each substring
    Arrays.fill(counter, 1);  // Initialize all counter values to 1
    int maxSubstrings = 1;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (s.charAt(i) == s.charAt(j)) {
                counter[i] = Math.max(counter[i], counter[j] + 1);
            }
        }
        maxSubstrings = Math.max(maxSubstrings, counter[i]);
    }
    return maxSubstrings;
}

