    Stack<String> stack = new Stack<>();
    for (String log : logs) {
        if (log.equals("../")) {
            if (stack.isEmpty()) {
                return 0;
            } else {
                stack.pop();
            }
        } else if (log.matches("^d\\d+/$")) {
            stack.push(log);
        }
    }
    return stack.size();
}

