    char[] arr = new char[n];
    Arrays.fill(arr, 'a');
    while (k > 0) {
        for (int i = n - 1; i >= 0; i--) {
            if (arr[i] == 'z') {
                arr[i] = 'a';
            } else {
                arr[i]++;
                break;
            }
        }
        k--;
    }
    return String.valueOf(arr);
}

