public static int findSmallestInteger(int n) {
    // Determine the number of digits in the given integer
    int numDigits = String.valueOf(n).length();

    // Initialize an array to hold the digits of the given integer
    int[] digits = new int[numDigits];

    // Fill the array with the digits of the given integer
    for (int i = 0; i < numDigits; i++) {
        digits[i] = n % 10;
        n /= 10;
    }

    // Sort the array in ascending order
    Arrays.sort(digits);

    // Find the smallest rearrangement of the digits
    int smallestInteger = 0;
    for (int i = 0; i < numDigits; i++) {
        smallestInteger += digits[i] * Math.pow(10, i);
    }

    // Return the smallest rearranged integer
    return smallestInteger;
}

