public static int calculateEnergy(String s) {
    int energy = 0;
    for (int i = 0; i < s.length(); i++) {
        int start = i;
        int end = i;
        char currChar = s.charAt(i);
        while (end < s.length() - 1 && s.charAt(end + 1) == currChar) {
            end++;
        }
        energy = Math.max(energy, end - start + 1);
        i = end;
    }
    return energy;
}

